css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 12px 18px 14px; margin-bottom: 12px;}
.mz .recuerda-titulo{font-size: 14px; font-weight: 700; margin-bottom: 6px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 13.5px; margin-bottom: 12px; line-height: 1.4;}
.mz .recuerda-idea strong{font-weight: 700;}
.mz .recuerda-ejemplos{display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 40px; align-items: flex-start; justify-items: center; padding: 6px 4px 4px;}
.mz .ej-mini{display: flex; flex-direction: column; align-items: center; gap: 10px;}
.mz .ej-mini .etiqueta{font-size: 10.5px; color: #444; font-family: sans-serif; font-weight: 700; letter-spacing: .5px; text-transform: uppercase; text-align: center;}
.mz .ej-col-mini{font-family: sans-serif; font-size: 19px; font-weight: 700; text-align: right; line-height: 1.35;}
.mz .ej-col-mini .cab{font-size: 11px; color: #666; font-weight: 700; letter-spacing: 4px; padding-right: 2px;}
.mz .ej-col-mini .lin{display: flex; justify-content: flex-end; align-items: center; gap: 8px;}
.mz .ej-col-mini .barra{border-top: 2px solid var(--bosque); padding-top: 3px;}
.mz .ej-horiz-mini{font-family: sans-serif; font-size: 19px; font-weight: 700; padding-top: 8px;}
.mz .columnas-grid{display: grid; grid-template-columns: repeat(6, 1fr); gap: 10px 8px; justify-items: center; margin-top: 4px;}
.mz .columnas-grid-4{display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px 12px; justify-items: center; margin-top: 4px;}
.mz .suma-col{font-family: sans-serif; font-size: 18px; font-weight: 700; text-align: right; line-height: 1.25; min-width: 65px;}
.mz .suma-col .lin{display: flex; justify-content: flex-end; align-items: center; gap: 6px;}
.mz .suma-col .sg{font-weight: 800; font-size: 16px;}
.mz .suma-col .barra{border-top: 2px solid var(--bosque); margin-top: 2px; padding-top: 4px; min-height: 28px;}
.mz .horiz-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8px 24px; margin-top: 4px;}
.mz .horiz-fila{display: flex; align-items: center; gap: 8px; font-family: sans-serif; font-size: 17px; font-weight: 700; justify-content: center;}
.mz .horiz-fila .caja{border: 1.5px solid var(--bosque); border-radius: 6px; width: 55px; height: 30px;}
.mz .serie-fila{display: grid; grid-template-columns: repeat(10, 1fr); gap: 5px; margin-top: 4px;}
.mz .serie-num{border: 2px solid var(--bosque); border-radius: 6px; height: 38px; display: flex; align-items: center; justify-content: center; font-family: sans-serif; font-size: 18px; font-weight: 800; background: #f0f0f0;}
.mz .serie-caja{border: 1.5px solid var(--bosque); border-radius: 6px; height: 38px;}
.mz .recuerda-idea{line-height: 1.875 !important;}
